"""RESULT.md = RESULT.tmpl.md with the fragments of mk_tables.py; usage: fill.py <control sweep prefix> <N> <c4 json> <N12 text> <C4 text> <units text> [<top prefix> <N top>]"""
import sys, json, subprocess
pref, N, c4f, n12, c4n, units = sys.argv[1:7]
extra = sys.argv[7:9]
subprocess.run([sys.executable, 'mk_tables.py', pref, N, c4f] + extra, capture_output=True, text=True, check=True)
fr = json.load(open('out/fragments.json')); both = json.load(open('out/an_both.json')); an = both['top']; c1 = an['comb1']; c2 = an['comb2']
z = c1['zeta']; Nf = float(both['Ntop'])
tz = {t['L']: t for t in c2['zeta']['table']}; tt = {t['L']: t for t in c2['TNR3_2.2']['table']}
Lm = max(l for l in tz if l <= 20)
c4 = json.load(open(c4f)); R = {r['obj']: r for r in c4['results']}
lastw = sorted(R['zeta']['p_fit'].keys(), key=lambda k: float(k.split('-')[0]))[-1]
table = '''| combination | statistic | sizes reached | zeta | comparison L-function | DH | heat (tau < 0) | sign-twisted primes | unimodular twist | E_a | T-NR | classification |
|---|---|---|---|---|---|---|---|---|---|---|---|
| 1. curvature charge D x screw response Psi x closed reserve | sign of Psi_F(r) = C_F(r) - sum c(n) n^{-1/2}(r - log n) and of the reserve R_n - eps(H_n) at every prime-power event; band 0 <= Psi <= 2 sum 1/gamma^2 | all prime powers q <= %(N)s (%(ev)s events) for zeta, the two L-functions and T-NR; 1e11 for the other controls (E_a(0.05) 2e11); DH: all n <= 2.2e9 | pass: min Psi %(zmin).5f, max %(zmax).5f (band 0.09242), min reserve %(zR).5f | L(chi_-4), L(chi_5): pass, inside their bands | first n = 315,860,174 (log 19.571; zero list predicts 19.572; full-form onset 3.56) | N | Psi never negative (to 1e9 / 1e10); band left and R_n < 0 at the first changed prime | as sign twists (zeta's bridge) | first q = 2,953 (a = 0.25), 33,355,457 (0.10), 105,076,853,033 (0.05); zero list predicts log q = 7.988, 17.324, 25.380 | first q = 8 (3,2.2), 81 (3,2.01), 4 (3,2.2, zeta's bridge); predicted log q 2.052, 4.392, 1.124 | CLOSED: the scalar is the Weil form on the box = sum (1 - cos gamma r)/gamma^2; every control fails where its zero list says and later than under the full form; E_a(0.05) passes 4.1e9 events to 1e11 |
| 2. proper-power memory x credit variation x reserve update | V(X) sqrt X / L for V(X) = sum_{p_n >= X} abs(c_{n+1} - c_n) against the bound 23 L + 34; B(r) - r/2 - kappa | credits: q <= %(N)s; B(r): prime powers to 1e16 | V sqrt X/L = 1.37-1.43 (L = 6..%(Lm)g), V/bound = 0.048-0.057; e^{r/6}(B - r/2 - kappa) = -2.0 +- 0.07 for 15 <= r <= 36.8 | B: L(chi_-4) has r/2 + const (-2.710 relative to zeta); credits: N (no pole, no state H) | N (coefficients on all n) | N | flips on 10%% of primes: V/bound = 8e2 .. 1.4e6; Liouville: H <= 0 at p = 29; B: even-k part identical to zeta's | B_F - r/2 = -19.8 at r = 36.8 (no r/2 term) | B_F - r/2 - kappa = +44.5 (a = 0.05), +1.99e4 (0.25) at r = 36.8; credits: N (own convex C) | credits: V/bound = 0.05-0.09 (3,2.2), within 0.4%% of zeta for L >= 14 (3,2.01): passes; B: grows like e^{0.404 r} from the event q^2 = 9 | CLOSED: the variation bound uses the smoothness of Lambda on the primes and the Chebyshev envelope of the state, not the zeros: it holds for T-NR (zeros at Re s = 0.904) and for thinned primes; B(r) is blind to real sign twists and fails for T-NR at one prime |
| 3. Toeplitz compression x gain ratio x spectral convergence | lambda_min(H_{h,m}) and G(eps) = lambda_max(C, B + eps I); onset W*(m) | m = 64 .. 4096 to W = 6; m = 16384 at W <= log 1e6 | positive: 1.0e-5 (m = 512), 8.6e-7 (2048), 8.9e-9 (16384, W = 13.8155); Arb LDL^T certificates m = 512 (W = 1..6) and m = 2048 (W = 6); G(1e-6) = 0.999994-0.999999 | positive: 2.7e-8 at m = 16384, W = 13.8155 | W*(m) = none (m <= 128), 4.275, 3.753, 3.678, 3.653, 3.647 (m = 256 .. 4096), in (3.60, 3.65] at m = 16384; rounds 2-3: 3.562 | N | 0.722-0.725 (Liouville, random); log 59 + 0.001..0.004 (flip10) | 0.728-0.731 | W*(4096) = 1.131 (a = 0.05), 0.869 (0.25); rounds 2-3: 1.007, 0.874 | 1.241-1.244 (3,2.2 own; rounds 2-3: 1.241); 1.103-1.106 (zeta's bridge) | CLOSED: Rayleigh-Ritz (PROVED): the compression is a subspace of the same form, W*(m) >= true onset; no failure below 0.8 x the round 2-3 onset; DH needs h gamma_off <= 1.4 |
| 4. flat-window diagonal x box defect x discrepancy floor | Psi_alpha(L) = sum (1 - cos((gamma - alpha)L))/(gamma - alpha)^2 on a grid of alpha; exponent p = 2 d log max_alpha abs(Psi_alpha)/dL; sign of min_alpha Psi_alpha(L) | alpha in [0,100], %(na)s values; L <= %(Lmax).1f (q <= %(N4)s); DH L <= 21.5 | never negative (min 0.0260); p = 0.63, 0.48, 0.32, 0.23, 0.18, %(pz)s on [3,6] .. [24, log N] (= 4/L) | never negative; p = %(p4)s, %(p5)s on the last window | first negative at L = 4.2, alpha = 84.45 (gamma_off = 85.70); p -> 0.62 | N | Liouville (zeta's bridge): negative at L = 0.8; p -> 1.00 | negative at L = 0.8; p -> 1.0 | negative at L = 6.3, 4.5, 2.7 (a = 0.05, 0.10, 0.25) at alpha = 13.1, 12.8, 11.9; p = %(pe)s, 0.23-0.25, 0.50-0.51 on the last two windows | T-NR(3,2.2): negative at L = 1.2 (zeta's bridge), 2.1 (own); p = 0.80-0.81 for L >= 6; T-NR(101,2.2): negative at 4.7 / 8.5, p = 0.20-0.23 | CLOSED: zeta's exponent is 4/L, not near 0, and within 0.05 of that of controls with zeros within 0.1 of the line; the sign test fails DH only at alpha within 6 of gamma_off for L <= 13 (verified height in the modulation frequency) |''' % dict(
    N='%.0e' % Nf, ev=format(z['events'], ','), zmin=min(z['min_psi'], 0.0213353), zmax=z['max_psi'], zR=min(z['min_R_low'], 0.0213282), Lm=Lm,
    na=format(c4['n_alpha'], ','), Lmax=R['zeta']['L'][-1], N4='%.0e' % c4['N'], pz='%.2f' % R['zeta']['p_fit'][lastw], p4='%.2f' % R['L_chi-4']['p_fit'][lastw], p5='%.2f' % R['L_chi5']['p_fit'][lastw],
    pe='%.2f-%.2f' % (R['Ea0.05']['p_fit'][lastw], R['Ea0.05']['p_fit']['20-24']))
s = open('RESULT.tmpl.md').read()
for k, v in fr.items(): s = s.replace('__%s__' % k, v)
s = s.replace('__TABLE__', table).replace('__N12__', n12).replace('__C4N12__', c4n).replace('__UNITS__', units)
assert '__' not in s.replace('__pycache__', ''), [l for l in s.split('\n') if '__' in l][:3]
open('RESULT.md', 'w').write(s); print('RESULT.md written', len(s))
